const header=document.querySelector('.site-header');
const menuToggle=document.querySelector('.menu-toggle');
const nav=document.querySelector('#main-nav');
const closeMenu=()=>{if(!menuToggle||!nav)return;menuToggle.setAttribute('aria-expanded','false');menuToggle.setAttribute('aria-label','Abrir menu');nav.classList.remove('open')};
menuToggle?.addEventListener('click',()=>{const open=menuToggle.getAttribute('aria-expanded')==='false';menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');nav.classList.toggle('open',open)});
nav?.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();document.querySelector('dialog[open]')?.close()}});
window.addEventListener('scroll',()=>header?.classList.toggle('scrolled',scrollY>40),{passive:true});
const routeChalets={
 '/chales/chale-1/':{name:'Chalé 1',eyebrow:'O refúgio',photo:'chale-madeira',alt:'Chalé 1 de madeira entre as árvores',caption:'O Chalé 1, por fora',title:'Um cantinho<br>entre as árvores.',description:'Um espaço para chegar, abrir a janela e deixar o verde fazer parte dos seus dias. Conheça esta acomodação e converse com a equipe sobre a sua estadia.',features:['Arquitetura em madeira','Varanda aberta para o verde','Consulte capacidade e comodidades'],gallery:['chale-madeira','varanda','quarto']},
 '/chales/chale-2/':{name:'Chalé 2',eyebrow:'A pausa',photo:'varanda',alt:'Chalé 2 com varanda e redes',caption:'A pausa do Chalé 2',title:'Um dia mais leve<br>começa na varanda.',description:'Redes, madeira e a mata como companhia. Uma acomodação para desacelerar no seu ritmo e aproveitar o tempo com calma.',features:['Varanda com redes','Vista para a vegetação','Consulte capacidade e comodidades'],gallery:['varanda','varanda-rede','descanso']},
 '/chales/chale-3/':{name:'Chalé 3',eyebrow:'O aconchego',photo:'quarto',alt:'Interior do Chalé 3 com janelas para a mata',caption:'O aconchego do Chalé 3',title:'Abra a janela.<br>Encontre o verde.',description:'Luz natural, madeira e a paisagem logo ali. Veja as imagens do Chalé 3 e fale com a equipe para confirmar os detalhes da acomodação.',features:['Interior acolhedor','Janelas para a natureza','Consulte capacidade e comodidades'],gallery:['quarto','quarto-natureza','varanda']},
 '/chales/chale-4/':{name:'Chalé 4',eyebrow:'Sem pressa',photo:'descanso',alt:'Espaço de descanso do Chalé 4',caption:'Um lugar para o Chalé 4',title:'Tem dias que pedem<br>um pouco de rede.',description:'Um espaço para ler mais uma página, esticar a conversa ou não fazer absolutamente nada. Conheça o Chalé 4 por imagens.',features:['Espaço para descansar','Varanda de madeira','Consulte capacidade e comodidades'],gallery:['descanso','chale-madeira','varanda-rede']},
 '/chales/chale-5/':{name:'Chalé 5',eyebrow:'A natureza',photo:'rio-una',alt:'Rio Una próximo ao Chalé 5',caption:'A natureza do Chalé 5',title:'Deixe o rio<br>levar a pressa.',description:'A paisagem do rio Una como companhia para dias leves. Descubra o Chalé 5 e pergunte à equipe sobre a melhor configuração para a sua viagem.',features:['Perto do rio Una','Paisagem cercada de verde','Consulte capacidade e comodidades'],gallery:['rio-una','deck-rio','chale-mata']}
};
const route=routeChalets[location.pathname];
if(route){document.title=`${route.name} — Paraíso do Una`;const heroTitle=document.getElementById('hero-title');if(heroTitle)heroTitle.innerHTML=`${route.name}<br><em>no Paraíso do Una.</em>`;const heroCopy=document.querySelector('.hero-content p');if(heroCopy)heroCopy.innerHTML=`${route.description}<br>Consulte datas e disponibilidade pelo WhatsApp.`;}
const photos=[{src:'chale-mata',alt:'Nosso refúgio: chalé entre as árvores'},{src:'varanda',alt:'A pausa: redes e verde na varanda'},{src:'quarto',alt:'O aconchego: o quarto e sua vista'},{src:'chale-madeira',alt:'O chalé de madeira na paisagem'},{src:'descanso',alt:'Sem pressa: espaço para descansar'},{src:'rio-una',alt:'A natureza: as águas do rio Una'},{src:'deck-rio',alt:'O deck de madeira à beira do rio'}];
if(route&&document.body.dataset.detail){document.getElementById('detail-hero-image').src=`/assets/${route.photo}.jpg`;document.getElementById('detail-hero-image').alt=route.alt;document.getElementById('detail-hero-caption').textContent=route.caption;document.getElementById('detail-kicker').textContent=route.name+' · '+route.eyebrow;document.getElementById('detail-title').innerHTML=route.title;document.getElementById('detail-description').textContent=route.description;document.getElementById('detail-long-description').textContent=route.description;document.getElementById('detail-features').replaceChildren(...route.features.map(text=>{const li=document.createElement('li');li.textContent=text;return li}));document.getElementById('booking-chalet-name').textContent=route.name.toLowerCase();route.gallery.forEach((src,index)=>{const img=document.getElementById(`detail-gallery-${index+1}`);if(img){img.src=`/assets/${src}.jpg`;img.alt=route.name+' — '+route.features[index];}});}
const story=document.getElementById('animacao-chale-4'),storyVideo=document.getElementById('chale4-video'),storyProgress=document.getElementById('story-progress-bar'),storySteps=[...document.querySelectorAll('.story-step')];
if(story&&storyVideo){const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)');let frame=0;const syncStory=()=>{frame=0;const range=Math.max(1,story.offsetHeight-innerHeight),progress=Math.min(1,Math.max(0,-story.getBoundingClientRect().top/range));if(!reduceMotion.matches&&storyVideo.readyState>=2&&Number.isFinite(storyVideo.duration)&&storyVideo.duration>0)storyVideo.currentTime=progress*storyVideo.duration;if(storyProgress)storyProgress.style.transform=`scaleX(${progress})`;const active=Math.min(storySteps.length-1,Math.floor(progress*storySteps.length));storySteps.forEach((step,index)=>step.classList.toggle('is-active',index===active))};const requestSync=()=>{if(!frame)frame=requestAnimationFrame(syncStory)};['loadedmetadata','loadeddata','canplay','canplaythrough'].forEach(event=>storyVideo.addEventListener(event,requestSync));window.addEventListener('scroll',requestSync,{passive:true});window.addEventListener('resize',requestSync);reduceMotion.addEventListener?.('change',requestSync);syncStory()}
const dialog=document.getElementById('lightbox');let currentPhoto=0;let previousFocus=null;
const activePhotos=()=>route&&document.body.dataset.detail?route.gallery.map((src,index)=>({src,alt:`${route.name} — ${route.features[index]||'detalhe da acomodação'}`})):photos;
function renderPhoto(){const list=activePhotos();const p=list[currentPhoto];const img=document.getElementById('lightbox-image');if(!img||!p)return;img.src=`/assets/${p.src}.jpg`;img.alt=p.alt;document.getElementById('lightbox-caption').textContent=p.alt;document.getElementById('lightbox-count').textContent=`${currentPhoto+1} / ${list.length}`}
function stepPhoto(delta){const list=activePhotos();currentPhoto=(currentPhoto+delta+list.length)%list.length;renderPhoto()}
document.querySelectorAll('[data-gallery]').forEach(button=>button.addEventListener('click',()=>{if(!dialog)return;previousFocus=button;currentPhoto=Number(button.dataset.gallery);renderPhoto();dialog.showModal();document.getElementById('lightbox-close').focus()}));
document.getElementById('lightbox-close')?.addEventListener('click',()=>dialog.close());document.getElementById('lightbox-prev')?.addEventListener('click',()=>stepPhoto(-1));document.getElementById('lightbox-next')?.addEventListener('click',()=>stepPhoto(1));
dialog?.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();stepPhoto(-1)}if(e.key==='ArrowRight'){e.preventDefault();stepPhoto(1)}});dialog?.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog?.addEventListener('close',()=>previousFocus?.focus());
const arrival=document.getElementById('check-in'),departure=document.getElementById('check-out'),guests=document.getElementById('guests'),form=document.getElementById('booking-form'),formError=document.getElementById('date-error');
if(form&&arrival&&departure&&guests){const localDate=date=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;const tomorrow=value=>{const d=new Date(value+'T12:00:00');d.setDate(d.getDate()+1);return localDate(d)};arrival.min=localDate(new Date());departure.min=tomorrow(arrival.min);arrival.addEventListener('change',()=>{formError.textContent='';departure.min=tomorrow(arrival.value||arrival.min);if(departure.value&&departure.value<=arrival.value)departure.value=''});departure.addEventListener('change',()=>formError.textContent='');form.addEventListener('submit',e=>{e.preventDefault();if(!arrival.value||!departure.value||arrival.value<localDate(new Date())||departure.value<=arrival.value){formError.textContent='Escolha uma chegada a partir de hoje e uma saída depois da chegada.';arrival.focus();return}const format=value=>new Intl.DateTimeFormat('pt-BR').format(new Date(value+'T12:00:00'));const selectedChalet=route?.name||'qualquer chalé disponível';const message=`Olá! Conheci o Paraíso do Una pelo site e gostaria de consultar o ${selectedChalet} para ${guests.value} pessoa${guests.value==='1'?'':'s'}, de ${format(arrival.value)} a ${format(departure.value)}. Podem me informar a disponibilidade e os valores?`;window.location.assign(`https://wa.me/5598991003860?text=${encodeURIComponent(message)}`)})}
